method match_parens(lst: array<string>) returns (result: string)
    requires |lst| == 2
    requires forall i :: 0 <= i < |lst| ==> (lst[i] == "(" || lst[i] == ")")
    ensures result == "Yes" || result == "No"
    ensures result == "Yes" <==> ((countOpen(lst[0]) + countOpen(lst[1]) >= countClose(lst[0]) + countClose(lst[1])) && (countClose(lst[0]) + countClose(lst[1]) >= countOpen(lst[0]) + countOpen(lst[1])))
    ensures result == "No" <==> !((countOpen(lst[0]) + countOpen(lst[1]) >= countClose(lst[0]) + countClose(lst[1])) && (countClose(lst[0]) + countClose(lst[1]) >= countOpen(lst[0]) + countOpen(lst[1])))

method countOpen(s: string) returns (count: int)
    ensures count >= 0
    decreases |s|
{
    count := 0;
    var i := 0;
    while i < |s|
        invariant 0 <= i <= |s|
        invariant count == CountOpen(s[0..i])
    {
        if s[i] == '(' {
            count := count + 1;
        }
        i := i + 1;
    }
}

method countClose(s: string) returns (count: int)
    ensures count >= 0
    decreases |s|
{
    count := 0;
    var i := 0;
    while i < |s|
        invariant 0 <= i <= |s|
        invariant count == CountClose(s[0..i])
    {
        if s[i] == ')' {
            count := count + 1;
        }
        i := i + 1;
    }
}

function CountOpen(s: string): int
{
    if |s| == 0 then 0 else (if s[|s| - 1] == '(' then 1 else 0) + CountOpen(s[0..|s| - 1])
}

function CountClose(s: string): int
{
    if |s| == 0 then 0 else (if s[|s| - 1] == ')' then 1 else 0) + CountClose(s[0..|s| - 1])
}

